function _show(v: V, d: V): string {
  // A value as mCRL2 prints it, following its shape d.
  const out: string[] = [];
  const stack: V[] = [[v, d]];
  for (;;) {
    const top = stack.pop();
    if (top === undefined) return out.join("");
    const [x, e] = top;
    if (typeof x === "string" && e === null) {
      out.push(x);
    } else if (e[0] === "v") {
      out.push(String(x));
    } else if (e[0] === "id") {
      out.push(e[1] + "(" + x + ")");
    } else if (e[0] === "l" || e[0] === "s") {
      const items: V[] = [[e[0] === "l" ? "[" : "{", null]];
      x.forEach((y: V, j: number) => {
        if (j) items.push([", ", null]);
        items.push([y, e[1]]);
      });
      items.push([e[0] === "l" ? "]" : "}", null]);
      for (let j = items.length - 1; j >= 0; j--) stack.push(items[j]);
    } else {
      const [c, fs, vs] = e[0] === "r" ? [e[1], e[2], x] : [e[1][x[0]][0], e[1][x[0]][1], x.slice(1)];
      const items: V[] = [[c, null]];
      if (fs.length) {
        items.push(["(", null]);
        vs.forEach((y: V, j: number) => {
          if (j) items.push([", ", null]);
          items.push([y, fs[j]]);
        });
        items.push([")", null]);
      }
      for (let j = items.length - 1; j >= 0; j--) stack.push(items[j]);
    }
  }
}

/** The entry as mCRL2 writes its action, ids as the model writes them (job(3)), for comparing state spaces. */
export function mcrl2Label(entry: Entry): string {
  const x: V = "event" in entry ? entry.event : entry.action;
  switch ("event" in entry ? "e:" + x.type : "a:" + x.type) {
    case "e:claim":
      return "c_claim";
    case "e:close":
      return "c_close";
    case "e:land":
      return "c_land";
    case "e:quiet":
      return "c_quiet";
    case "e:release":
      return "c_release";
    case "e:sign":
      return "c_sign";
    case "a:finish":
      return "c_finish";
    case "a:pause":
      return "c_pause";
    case "a:stall":
      return "c_stall";
    case "a:work":
      return "c_work";
  }
  throw new Error("not an entry of this model");
}

